sys_ux_data_broker_transform.script:
function transform(input) {
    var employees = [{
        "id": "none",
        "label": "-- None --"
    }];
    // get employees under manager
    var user = new GlideRecord("sys_user");
    user.addEncodedQuery("active=true^roles=x_1324635_grc_ops.grc_interns");
    user.query();
    while (user.next()) {
        employees.push({
            "id": user.sys_id.toString(),
            "label": user.name.getDisplayValue(),
			"avatarProps": {
            "userName": user.user_name.toString(),
            "imageSrc": user.photo.getDisplayValue()+"?t=small",
            "presence": "away"
        }
        });
    }

    return employees;
}
